mapper.select:
select f.forbidden_id, f.semester_id, f.teacher_id, t.teacher_name, f.week_day, f.start_period, f.end_period, f.reason, f.status, f.del_flag, f.create_by, f.create_time, f.update_by, f.update_time, f.remark from tpm_teacher_forbidden f left join brm_teacher t on f.teacher_id = t.teacher_id
f.del_flag = '0' and (f.semester_id = #{semesterId} or f.semester_id is null) and f.teacher_id = #{teacherId} and t.teacher_name like concat('%', #{teacherName}, '%') and f.week_day = #{weekDay} and f.status = #{status}
order by f.teacher_id asc, f.week_day asc, f.start_period asc

mapper.update:
update tpm_teacher_forbidden
semester_id = #{semesterId}, teacher_id = #{teacherId}, week_day = #{weekDay}, start_period = #{startPeriod}, end_period = #{endPeriod}, reason = #{reason}, status = #{status}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
where forbidden_id = #{forbiddenId}
